import { randomUUID } from 'crypto';
import { NextResponse } from 'next/server';
import { createServiceSupabaseClient } from '@/runtime/supabase/server';
export const dynamic='force-dynamic';
function credential(req:Request){const token=req.headers.get('authorization')?.replace(/^Bearer\s+/i,'').trim();if(!token)return null;try{const map=JSON.parse(process.env.SFI_EXTERNAL_API_KEYS_JSON||'{}') as Record<string,{label?:string;scopes?:string[]}>;const c=map[token];return c&&(c.scopes?.includes('propose')||c.scopes?.includes('*'))?c:null}catch{return null}}
export async function POST(req:Request){const cred=credential(req);if(!cred)return NextResponse.json({ok:false,error:'unauthorized'},{status:401});const body=await req.json().catch(()=>({})) as Record<string,unknown>;const title=String(body.title||'').trim(),summary=String(body.summary||'').trim();if(!title||!summary)return NextResponse.json({ok:false,error:'title_and_summary_required'},{status:400});const db=createServiceSupabaseClient();const row={id:randomUUID(),title,status:'proposed',risk_level:String(body.risk_level||'medium'),approval_required:true,expected_field_delta:{proposalType:'external_agent_proposal',payload:{summary,requested_action:body.action??null,source:'external_agent_gateway',credential_label:cred.label||'external-agent',submitted_at:new Date().toISOString()}},proportionality_check:{external:true,human_approval_required:true}};const r=await db.from('action_proposals').insert(row).select('id,title,status,risk_level,created_at').single();if(r.error)return NextResponse.json({ok:false,error:'proposal_write_failed',details:r.error.message},{status:500});return NextResponse.json({ok:true,data:r.data,message:'Proposal recorded. ROOT approval is required before any governed realization.'},{status:201});}
